/// Uses IMemoryCache with sliding expiration.
/// </summary>
public async Task<Consumer8Data> GetCachedConsumer8Async(string key)
{
    var cacheKey = $"Consumer8_{key}";

    if (_cache.TryGetValue(cacheKey, out Consumer8Data cached))
